arguments.command:
curl -s -w "\nHTTP Status: %{http_code}\n" https://github.feralfantasies.co.uk/push \
  -X POST \
  -H "Content-Type: application/json" \
  -H "X-GitHub-Event: push" \
  -d '{
    "ref": "refs/heads/main",
    "repository": {"name": "test-repo", "full_name": "feralfantasies/test-repo"},
    "commits": [{"id": "abc123", "message": "test commit"}],
    "pusher": {"name": "acleveland"}
  }' 2>&1

