arguments.command:
kubectl get secret github-token -n default -o json 2>/dev/null | python3 -c "
import sys, json, base64
data = json.load(sys.stdin)
for k, v in data['data'].items():
    val = base64.b64decode(v).decode()
    if val.startswith('ghp_') or val.startswith('github_pat_'):
        print(f'{k}: {val[:10]}...{val[-5:]}')
    else:
        print(f'{k}: {val[:50]}' )
"
